// ═══════════════════════════════════════════════════════════════════════════════
// GRAIN TERMINAL SIMULATOR v3.0 - COM ELETROCENTRO
// Terminal de Grãos 2000 t/h - Exportação Marítima + Sistema Elétrico Completo
// ═══════════════════════════════════════════════════════════════════════════════
//
// FLUXO DO PROCESSO:
// Armazém → Vazadores (ARZ) → Correia 01 → Correia 02 → Elevador → 
// Balança de Fluxo → Correia 03 → Tripper/Shiploader
//
// EQUIPAMENTOS DE PROCESSO:
// - MOE01: Moega de Recebimento (caminhões)
// - ARZ_GATES: 4 Vazadores de Armazém
// - CORR01: Correia Coletora (600 t/h)
// - CORR02: Correia Transportadora (1200 t/h)
// - ELV01: Elevador de Canecas (1500 t/h)
// - BLC01: Balança de Fluxo (2000 t/h) - CRÍTICO!
// - CORR03: Correia de Embarque (2000 t/h)
// - TRP01: Tripper Car
// - SLD01: Shiploader (2000 t/h)
//
// ELETROCENTRO:
// - TR01: Transformador Principal 1000kVA (13.8kV/440V)
// - CCM01: Centro de Controle de Motores (8 gavetas)
// - PM_GERAL: Multimedidor Entrada Geral
// - PM_CCM01: Multimedidor CCM01
// - PM_ILUM: Multimedidor Iluminação
// - BC01: Banco de Capacitores 200kVAr
// - REL_GERAL: Relé de Proteção Principal (50/51, 49, 27/59)
// ═══════════════════════════════════════════════════════════════════════════════

const timestamp = new Date().toISOString();

let state = context.get('state') || {
    running: true,
    time_s: 0,
    start_time: Date.now(),
    operation_mode: 'LOADING', // LOADING, RECEIVING, IDLE

    // ═══ MOEGA DE RECEBIMENTO (MOE01) ═══
