        level_pct: 35,        // Nível da moega (%)
        flow_tph: 0,          // Vazão de descarga (t/h)
        truck_count: 0,       // Contador de caminhões
        weight_t: 0,          // Peso atual (t)
        capacity_t: 100,      // Capacidade máxima (t)
        gate_open: false,     // Comporta aberta
        vibrator_on: false    // Vibrador ativo
    },

    // ═══ VAZADORES DE ARMAZÉM (4 unidades) ═══
    // Cada vazador: máx 300 t/h, abertura 0-100%
