            name: 'Correia Coletora',
            running: true,
            speed_mps: 0,         // Velocidade real (m/s)
            speed_sp: 2.5,        // Setpoint velocidade
            flow_tph: 0,          // Vazão atual
            capacity_tph: 600,    // Capacidade nominal
            load_pct: 0,          // Carga (%)
            power_kw: 0,          // Potência consumida
            current_a: 0,         // Corrente motor
            motor_temp_c: 35,     // Temp motor
            bearing_temp_c: 40,   // Temp mancal
            vibration_mms: 1.2,   // Vibração
            belt_slip: false,     // Patinamento
            pull_cord: false      // Cordinha puxada
        },
        CORR02: {
            name: 'Correia Transportadora',
