    },

    // ═══ COMUNICAÇÃO ═══
    comm: {
        messages_sent: 0,
        messages_ok: 0,
        messages_fail: 0
    },

    // ═══ ALARMES ═══
    alarms: [],

    // ═══════════════════════════════════════════════════════════════
    // ELETROCENTRO - Sistema Elétrico Completo
    // ═══════════════════════════════════════════════════════════════

    // ═══ TRANSFORMADOR PRINCIPAL (TR01) - 1000kVA, 13.8kV/440V ═══
    transformer: {
        nominal_kva: 1000,
        primary_v: 13800,
        secondary_v: 440,
        tap_position: 3,           // Tap 1-5 (3 = nominal)
        oil_temp_c: 55,
        winding_temp_c: 65,
        load_pct: 0,
        power_kw: 0,
        power_kvar: 0,
        power_kva: 0,
        efficiency: 0.985,
        energized: true,
        cooling_fans_on: false,
        buchholz_alarm: false,
        pressure_relief_alarm: false,
        oil_level_ok: true
    },

    // ═══ ENTRADA GERAL - Medição Multimedidor PM_GERAL ═══
    pmGeral: {
        voltage_l1_v: 440,
        voltage_l2_v: 440,
        voltage_l3_v: 440,
        voltage_l1l2_v: 762,
        voltage_l2l3_v: 762,
        voltage_l3l1_v: 762,
        current_l1_a: 0,
        current_l2_a: 0,
        current_l3_a: 0,
        current_n_a: 0,
        power_kw: 0,
        power_kvar: 0,
        power_kva: 0,
        power_factor: 0.85,
        frequency_hz: 60.0,
        energy_kwh: 0,
        energy_kvarh: 0,
        demand_kw: 0,
        max_demand_kw: 0,
        thd_v_pct: 2.5,
        thd_i_pct: 8.0
    },

    // ═══ CCM01 - Centro de Controle de Motores (8 gavetas) ═══
    ccm: {
        // Gaveta 1: Motor CORR01 - Correia Coletora (15kW)
        drawer1: {
            name: 'CORR01', motor_kw: 15, starter_type: 'DOL',
            running: false, breaker_on: true, overload_trip: false, fault: false,
            current_a: 0, power_kw: 0, thermal_pct: 0, starts_today: 0,
            last_start: null, run_hours: 0
        },
        // Gaveta 2: Motor CORR02 - Correia Transportadora (30kW)
        drawer2: {
            name: 'CORR02', motor_kw: 30, starter_type: 'SOFTSTART',
            running: false, breaker_on: true, overload_trip: false, fault: false,
            current_a: 0, power_kw: 0, thermal_pct: 0, starts_today: 0,
            softstart_ramp_pct: 0, softstart_current_limit: 350
        },
        // Gaveta 3: Motor CORR03 - Correia de Embarque (45kW)
        drawer3: {
            name: 'CORR03', motor_kw: 45, starter_type: 'SOFTSTART',
            running: false, breaker_on: true, overload_trip: false, fault: false,
            current_a: 0, power_kw: 0, thermal_pct: 0, starts_today: 0,
            softstart_ramp_pct: 0, softstart_current_limit: 400
        },
        // Gaveta 4: Motor ELV01 - Elevador de Canecas (75kW)
        drawer4: {
            name: 'ELV01', motor_kw: 75, starter_type: 'VFD',
            running: false, breaker_on: true, overload_trip: false, fault: false,
            current_a: 0, power_kw: 0, thermal_pct: 0, starts_today: 0,
            vfd_freq_hz: 0, vfd_speed_pct: 0, vfd_dc_bus_v: 0, vfd_temp_c: 35
        },
        // Gaveta 5: Motor SLD01 - Shiploader Principal (90kW)
        drawer5: {
            name: 'SLD01_MAIN', motor_kw: 90, starter_type: 'VFD',
            running: false, breaker_on: true, overload_trip: false, fault: false,
            current_a: 0, power_kw: 0, thermal_pct: 0, starts_today: 0,
            vfd_freq_hz: 0, vfd_speed_pct: 0, vfd_dc_bus_v: 0, vfd_temp_c: 35
        },
        // Gaveta 6: Motor SLD01_SLEW - Giro Shiploader (22kW)
        drawer6: {
            name: 'SLD01_SLEW', motor_kw: 22, starter_type: 'VFD',
            running: false, breaker_on: true, overload_trip: false, fault: false,
            current_a: 0, power_kw: 0, thermal_pct: 0, starts_today: 0,
            vfd_freq_hz: 0, vfd_speed_pct: 0
        },
        // Gaveta 7: Motor SLD01_BOOM - Lança Shiploader (15kW)
        drawer7: {
            name: 'SLD01_BOOM', motor_kw: 15, starter_type: 'DOL',
            running: false, breaker_on: true, overload_trip: false, fault: false,
            current_a: 0, power_kw: 0, thermal_pct: 0, starts_today: 0
        },
        // Gaveta 8: Motor TRP01 - Tripper Car (7.5kW)
        drawer8: {
            name: 'TRP01', motor_kw: 7.5, starter_type: 'VFD',
            running: false, breaker_on: true, overload_trip: false, fault: false,
            current_a: 0, power_kw: 0, thermal_pct: 0, starts_today: 0,
            vfd_freq_hz: 0, vfd_speed_pct: 0
        }
    },

    // ═══ MULTIMEDIDOR CCM (PM_CCM01) ═══
    pmCcm: {
        voltage_l1_v: 440,
        voltage_l2_v: 440,
        voltage_l3_v: 440,
        current_l1_a: 0,
        current_l2_a: 0,
        current_l3_a: 0,
        power_kw: 0,
        power_kvar: 0,
        power_factor: 0.85,
        energy_kwh: 0
    },

    // ═══ MULTIMEDIDOR ILUMINAÇÃO (PM_ILUM) ═══
    pmIlum: {
        voltage_v: 220,
        current_a: 25,
        power_kw: 5.5,
        energy_kwh: 0,
        power_factor: 0.95
    },

    // ═══ BANCO DE CAPACITORES (BC01) - 200kVAr ═══
    capacitorBank: {
        nominal_kvar: 200,
        active_kvar: 0,
        stages: 8,                  // 8 estágios de 25kVAr
        active_stages: 0,
        auto_mode: true,
        target_pf: 0.92,
        current_pf: 0.85,
        voltage_v: 440,
        current_a: 0,
        temperature_c: 35,
        discharge_time_s: 0,
        overvoltage_trip: false,
        overcurrent_trip: false
    },

    // ═══ RELÉ DE PROTEÇÃO PRINCIPAL (REL_GERAL) ═══
    mainRelay: {
        // Função 50/51 - Sobrecorrente
        f50_51_enabled: true,
        f50_pickup_a: 1500,         // Instantâneo
        f51_pickup_a: 800,          // Temporizado
        f51_time_dial: 0.5,
        f50_51_trip: false,
        f50_51_alarm: false,

        // Função 49 - Térmica
        f49_enabled: true,
        f49_thermal_pct: 0,
        f49_trip_pct: 105,
        f49_alarm_pct: 90,
        f49_trip: false,
        f49_alarm: false,

        // Função 27/59 - Sub/Sobretensão
        f27_59_enabled: true,
        f27_pickup_v: 396,          // -10%
        f59_pickup_v: 484,          // +10%
        f27_trip: false,
        f59_trip: false,
        f27_alarm: false,
        f59_alarm: false,

        // Função 81 - Frequência
        f81_enabled: true,
        f81_under_hz: 58.5,
        f81_over_hz: 61.5,
        f81_trip: false,

        // Status geral
        any_trip: false,
        any_alarm: false,
        last_trip_code: '',
        last_trip_time: null
    },

    // ═══ TOTALIZADORES ELÉTRICOS ═══
    electricTotals: {
        energy_kwh_today: 0,
        energy_kwh_month: 0,
        energy_kvarh_today: 0,
        peak_demand_kw: 0,
        peak_demand_time: null,
        power_factor_avg: 0.85,
        runtime_h: 0
    },

    lastUpdate: Date.now()
};

const now = Date.now();
const dt = Math.min((now - state.lastUpdate) / 1000, 2);
state.lastUpdate = now;
state.time_s += dt;
state.totals.runtime_h += dt / 3600;

// ═══════════════════════════════════════════════════════════════
// FUNÇÕES AUXILIARES
// ═══════════════════════════════════════════════════════════════

const firstOrderLag = (current, target, tau, dt) => {
    const alpha = dt / (tau + dt);
    return current + alpha * (target - current);
};

const noise = (base, variance) => 
    base * (1 + (Math.random() - 0.5) * 2 * variance);

const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

const checkAlarm = (condition, id, message, severity) => {
    const exists = state.alarms.find(a => a.id === id);
    if (condition && !exists) {
        state.alarms.push({ id, message, severity, time: state.time_s });
    } else if (!condition && exists) {
        state.alarms = state.alarms.filter(a => a.id !== id);
    }
};

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DOS VAZADORES (ARZ_GATES)
// ═══════════════════════════════════════════════════════════════

let totalGateFlow = 0;
state.gates.forEach((gate, i) => {
    if (!gate.fault) {
        // Atuação hidráulica - resposta lenta
        gate.opening = firstOrderLag(gate.opening, gate.setpoint, gate.tau, dt);
    }

    // Vazão proporcional à abertura (não linear)
    const flowFactor = Math.pow(gate.opening / 100, 0.8);
    const targetFlow = flowFactor * gate.max_flow;
    gate.flow = noise(firstOrderLag(gate.flow, targetFlow, 1.5, dt), 0.03);
    gate.flow = Math.max(0, gate.flow);

    totalGateFlow += gate.flow;

    // Alarme de falha
    checkAlarm(gate.fault, `ARZ_GATE${gate.id}_FAULT`, `Vazador ${gate.id} em falha`, 'HIGH');
});

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DAS CORREIAS
// ═══════════════════════════════════════════════════════════════

function simulateBelt(belt, inputFlow, dt) {
    if (!belt.running || belt.pull_cord) {
        belt.speed_mps = firstOrderLag(belt.speed_mps, 0, 3.0, dt);
        belt.flow_tph = 0;
        belt.load_pct = 0;
        belt.power_kw = belt.speed_mps > 0.1 ? 5 : 0; // Potência residual
        belt.current_a = belt.power_kw * 1000 / (440 * 1.732 * 0.85);
        belt.motor_temp_c = firstOrderLag(belt.motor_temp_c, 25, 120, dt);
        return 0;
    }

    // Velocidade com rampa
    belt.speed_mps = firstOrderLag(belt.speed_mps, belt.speed_sp, 5.0, dt);

    // Vazão limitada pela capacidade
    belt.flow_tph = Math.min(inputFlow, belt.capacity_tph);
    belt.load_pct = (belt.flow_tph / belt.capacity_tph) * 100;

    // Potência: P = k1 + k2 * carga + k3 * velocidade
    const k1 = 8;   // Potência base
    const k2 = belt.capacity_tph / 1000 * 25;  // Fator de carga
    const k3 = 5;   // Fator de velocidade
    belt.power_kw = noise(k1 + (belt.load_pct/100) * k2 + belt.speed_mps * k3, 0.02);

    // Corrente do motor
    belt.current_a = belt.power_kw * 1000 / (440 * 1.732 * 0.85);

    // Temperatura do motor (sobe com carga)
    const tempTarget = 35 + (belt.load_pct / 100) * 25;
    belt.motor_temp_c = firstOrderLag(belt.motor_temp_c, tempTarget, 300, dt);
    belt.motor_temp_c = noise(belt.motor_temp_c, 0.01);

    // Temperatura do mancal
    belt.bearing_temp_c = belt.motor_temp_c + noise(5, 0.1);

    // Vibração (aumenta com carga e tempo)
    belt.vibration_mms = noise(0.8 + (belt.load_pct / 100) * 0.8, 0.15);

    // Detecção de patinamento
    belt.belt_slip = belt.load_pct > 95 && Math.random() < 0.001;

    // Alarmes
    const beltName = Object.keys(state.belts).find(k => state.belts[k] === belt);
    checkAlarm(belt.motor_temp_c > 65, `${beltName}_HIGH_TEMP`, `${beltName} temp motor alta: ${belt.motor_temp_c.toFixed(1)}°C`, 'MEDIUM');
    checkAlarm(belt.bearing_temp_c > 70, `${beltName}_BEARING_TEMP`, `${beltName} temp mancal alta: ${belt.bearing_temp_c.toFixed(1)}°C`, 'HIGH');
    checkAlarm(belt.vibration_mms > 4.0, `${beltName}_HIGH_VIB`, `${beltName} vibração alta: ${belt.vibration_mms.toFixed(1)} mm/s`, 'MEDIUM');
    checkAlarm(belt.belt_slip, `${beltName}_SLIP`, `${beltName} patinamento detectado`, 'HIGH');
    checkAlarm(belt.pull_cord, `${beltName}_PULLCORD`, `${beltName} cordinha de emergência acionada`, 'CRITICAL');

    return belt.flow_tph;
}

// CORR01: Recebe dos vazadores
const corr01Output = simulateBelt(state.belts.CORR01, totalGateFlow, dt);

// CORR02: Recebe da CORR01
const corr02Output = simulateBelt(state.belts.CORR02, corr01Output, dt);

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DO ELEVADOR (ELV01)
// ═══════════════════════════════════════════════════════════════

if (state.elevator.running) {
    state.elevator.speed_mps = firstOrderLag(state.elevator.speed_mps, state.elevator.speed_sp, 8.0, dt);
    state.elevator.flow_tph = Math.min(corr02Output, state.elevator.capacity_tph);

    // Potência do elevador (maior que correias devido à elevação)
    const liftHeight = 45; // metros
    const liftPower = (state.elevator.flow_tph / 3600) * 9.81 * liftHeight / 0.7; // kW
    state.elevator.power_kw = noise(20 + liftPower, 0.02);
    state.elevator.current_a = state.elevator.power_kw * 1000 / (440 * 1.732 * 0.85);

    // Temperaturas
    state.elevator.motor_temp_c = noise(firstOrderLag(state.elevator.motor_temp_c, 45 + (state.elevator.flow_tph/1500) * 20, 200, dt), 0.01);
    state.elevator.bearing_temp_c = state.elevator.motor_temp_c + noise(8, 0.1);

    // Vibração
    state.elevator.vibration_mms = noise(1.2 + (state.elevator.flow_tph/1500) * 0.8, 0.1);

    // Contagem de canecas
    state.elevator.bucket_count += Math.floor(state.elevator.flow_tph / 50 * dt);

    // Nível no pé do elevador
    state.elevator.boot_level_pct = clamp(30 + (corr02Output - state.elevator.flow_tph) * 0.1, 10, 90);

    // Pressão na cabeça
    state.elevator.head_pressure = noise((state.elevator.flow_tph / 1500) * 100, 0.05);
} else {
    state.elevator.speed_mps = firstOrderLag(state.elevator.speed_mps, 0, 10, dt);
    state.elevator.flow_tph = 0;
    state.elevator.power_kw = 0;
}

// Alarmes do elevador
checkAlarm(state.elevator.motor_temp_c > 70, 'ELV01_HIGH_TEMP', `Elevador temp alta: ${state.elevator.motor_temp_c.toFixed(1)}°C`, 'HIGH');
checkAlarm(state.elevator.boot_level_pct > 80, 'ELV01_BOOT_HIGH', `Elevador nível pé alto: ${state.elevator.boot_level_pct.toFixed(0)}%`, 'MEDIUM');
checkAlarm(state.elevator.vibration_mms > 4.5, 'ELV01_HIGH_VIB', `Elevador vibração alta: ${state.elevator.vibration_mms.toFixed(1)} mm/s`, 'HIGH');

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DA BALANÇA DE FLUXO (BLC01) - CRÍTICO!
// ═══════════════════════════════════════════════════════════════

const scaleInput = state.elevator.flow_tph;
state.scale.flow_tph = noise(scaleInput, state.scale.accuracy_pct / 100);
state.scale.belt_load_kg_m = state.scale.flow_tph / 3.6 / state.scale.speed_mps;

// Totalização
const massIncrement = (state.scale.flow_tph / 3600) * dt;
state.scale.total_t += massIncrement;
state.scale.daily_total_t += massIncrement;

// Alarmes da balança
checkAlarm(!state.scale.calibration_ok, 'BLC01_CAL_FAULT', 'Balança: calibração vencida', 'HIGH');
checkAlarm(!state.scale.zero_ok, 'BLC01_ZERO_FAULT', 'Balança: erro de zero', 'MEDIUM');
checkAlarm(Math.abs(state.scale.flow_tph - state.scale.flow_sp) > 200, 'BLC01_FLOW_DEV', `Balança: desvio de vazão ${(state.scale.flow_tph - state.scale.flow_sp).toFixed(0)} t/h`, 'LOW');

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DA CORREIA 03 (após balança)
// ═══════════════════════════════════════════════════════════════

const corr03Output = simulateBelt(state.belts.CORR03, state.scale.flow_tph, dt);

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DO TRIPPER CAR (TRP01)
// ═══════════════════════════════════════════════════════════════

const tripperError = state.tripper.target_position - state.tripper.position_m;
if (Math.abs(tripperError) > 0.5) {
    state.tripper.speed_mpm = clamp(tripperError * 2, -30, 30);
    state.tripper.position_m += (state.tripper.speed_mpm / 60) * dt;
} else {
    state.tripper.speed_mpm = 0;
}

state.tripper.limit_left = state.tripper.position_m < 5;
state.tripper.limit_right = state.tripper.position_m > 195;
state.tripper.position_m = clamp(state.tripper.position_m, 0, 200);

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DO SHIPLOADER (SLD01)
// ═══════════════════════════════════════════════════════════════

const sldInput = corr03Output;
state.shiploader.flow_tph = noise(firstOrderLag(state.shiploader.flow_tph, Math.min(sldInput, state.shiploader.flow_sp), 2.0, dt), 0.02);

// Potência do shiploader
state.shiploader.power_kw = noise(30 + (state.shiploader.flow_tph / 2000) * 120, 0.02);
state.shiploader.current_a = state.shiploader.power_kw * 1000 / (440 * 1.732 * 0.85);

// Movimento da lança (oscilação suave)
state.shiploader.boom_angle_deg = noise(12, 0.02);
state.shiploader.slewing_deg = noise(0, 0.01) + Math.sin(state.time_s / 60) * 5;
state.shiploader.shuttle_pos_m = clamp(15 + Math.sin(state.time_s / 30) * 5, 5, 25);

// Carregamento do navio
const loadedIncrement = (state.shiploader.flow_tph / 3600) * dt;
state.shiploader.loaded_t += loadedIncrement;
state.totals.loaded_t += loadedIncrement;
state.totals.daily_loaded_t += loadedIncrement;

// ═══════════════════════════════════════════════════════════════
// ATUALIZAÇÃO DO ARMAZÉM
// ═══════════════════════════════════════════════════════════════

state.warehouse.stock_t -= loadedIncrement;
if (state.warehouse.stock_t < 5000) {
    state.warehouse.stock_t = 45000; // Simula reposição
}

// ═══════════════════════════════════════════════════════════════
// SIMULAÇÃO DO ELETROCENTRO
// ═══════════════════════════════════════════════════════════════

// Função para calcular dados do CCM baseado nos equipamentos
function updateCCMDrawer(drawer, equipmentRunning, equipmentPower, equipmentCurrent) {
    drawer.running = equipmentRunning;
    drawer.power_kw = equipmentRunning ? equipmentPower : 0;
    drawer.current_a = equipmentRunning ? equipmentCurrent : 0;

    // Cálculo térmico (aquecimento gradual)
    const thermalTarget = drawer.running ? (drawer.current_a / (drawer.motor_kw * 1.8)) * 100 : 0;
    drawer.thermal_pct = firstOrderLag(drawer.thermal_pct || 0, thermalTarget, 60, dt);

    // VFD específico
    if (drawer.starter_type === 'VFD' && drawer.running) {
        drawer.vfd_freq_hz = noise(60, 0.01);
        drawer.vfd_speed_pct = noise(100, 0.02);
        drawer.vfd_dc_bus_v = noise(620, 0.01);
        drawer.vfd_temp_c = firstOrderLag(drawer.vfd_temp_c || 35, 35 + drawer.power_kw * 0.3, 120, dt);
    }

    // Softstart específico
    if (drawer.starter_type === 'SOFTSTART' && drawer.running) {
        drawer.softstart_ramp_pct = 100; // Já completou rampa
    }

    // Contador de horas
    if (drawer.running) {
        drawer.run_hours = (drawer.run_hours || 0) + dt / 3600;
    }
}

// Atualizar gavetas do CCM com dados dos equipamentos
updateCCMDrawer(state.ccm.drawer1, state.belts.CORR01.running, state.belts.CORR01.power_kw, state.belts.CORR01.current_a);
updateCCMDrawer(state.ccm.drawer2, state.belts.CORR02.running, state.belts.CORR02.power_kw, state.belts.CORR02.current_a);
updateCCMDrawer(state.ccm.drawer3, state.belts.CORR03.running, state.belts.CORR03.power_kw, state.belts.CORR03.current_a);
updateCCMDrawer(state.ccm.drawer4, state.elevator.running, state.elevator.power_kw, state.elevator.current_a);
updateCCMDrawer(state.ccm.drawer5, state.shiploader.flow_tph > 0, state.shiploader.power_kw * 0.6, state.shiploader.current_a * 0.6);
updateCCMDrawer(state.ccm.drawer6, Math.abs(state.shiploader.slewing_deg) > 0.5, 8, 15);
updateCCMDrawer(state.ccm.drawer7, state.shiploader.boom_angle_deg !== 12, 5, 10);
updateCCMDrawer(state.ccm.drawer8, Math.abs(state.tripper.speed_mpm) > 0, 3, 6);

// ═══ CÁLCULO DE POTÊNCIA TOTAL DO CCM ═══
const ccmTotalPower = Object.values(state.ccm).reduce((sum, d) => sum + (d.power_kw || 0), 0);
const ccmTotalCurrent = Object.values(state.ccm).reduce((sum, d) => sum + (d.current_a || 0), 0);

// ═══ MULTIMEDIDOR CCM (PM_CCM01) ═══
state.pmCcm.power_kw = noise(ccmTotalPower, 0.01);
state.pmCcm.current_l1_a = noise(ccmTotalCurrent / 3, 0.02);
state.pmCcm.current_l2_a = noise(ccmTotalCurrent / 3, 0.02);
state.pmCcm.current_l3_a = noise(ccmTotalCurrent / 3, 0.02);
state.pmCcm.voltage_l1_v = noise(440, 0.005);
state.pmCcm.voltage_l2_v = noise(440, 0.005);
state.pmCcm.voltage_l3_v = noise(440, 0.005);
state.pmCcm.power_kvar = ccmTotalPower * 0.62; // tan(acos(0.85))
state.pmCcm.power_factor = 0.85 + (state.capacitorBank.active_stages * 0.01);
state.pmCcm.energy_kwh += (ccmTotalPower / 3600) * dt;

// ═══ MULTIMEDIDOR ILUMINAÇÃO (PM_ILUM) ═══
state.pmIlum.power_kw = noise(5.5, 0.05);
state.pmIlum.current_a = noise(25, 0.03);
state.pmIlum.energy_kwh += (state.pmIlum.power_kw / 3600) * dt;

// ═══ POTÊNCIA TOTAL DA PLANTA ═══
const totalPower = ccmTotalPower + state.pmIlum.power_kw + 10; // +10kW auxiliares
const totalReactivePower = totalPower * 0.62 - state.capacitorBank.active_kvar;
const totalApparentPower = Math.sqrt(totalPower * totalPower + totalReactivePower * totalReactivePower);

// ═══ MULTIMEDIDOR GERAL (PM_GERAL) ═══
const totalCurrent = totalApparentPower * 1000 / (440 * 1.732);
state.pmGeral.power_kw = noise(totalPower, 0.01);
state.pmGeral.power_kvar = noise(totalReactivePower, 0.02);
state.pmGeral.power_kva = noise(totalApparentPower, 0.01);
state.pmGeral.current_l1_a = noise(totalCurrent / 3, 0.02);
state.pmGeral.current_l2_a = noise(totalCurrent / 3 * 1.02, 0.02);
state.pmGeral.current_l3_a = noise(totalCurrent / 3 * 0.98, 0.02);
state.pmGeral.current_n_a = noise(totalCurrent * 0.02, 0.1);
state.pmGeral.voltage_l1_v = noise(440, 0.003);
state.pmGeral.voltage_l2_v = noise(440, 0.003);
state.pmGeral.voltage_l3_v = noise(440, 0.003);
state.pmGeral.voltage_l1l2_v = noise(762, 0.003);
state.pmGeral.voltage_l2l3_v = noise(762, 0.003);
state.pmGeral.voltage_l3l1_v = noise(762, 0.003);
state.pmGeral.frequency_hz = noise(60.0, 0.001);
state.pmGeral.power_factor = totalPower / totalApparentPower;
state.pmGeral.energy_kwh += (totalPower / 3600) * dt;
state.pmGeral.energy_kvarh += (Math.abs(totalReactivePower) / 3600) * dt;
state.pmGeral.demand_kw = firstOrderLag(state.pmGeral.demand_kw || 0, totalPower, 900, dt); // 15min
state.pmGeral.max_demand_kw = Math.max(state.pmGeral.max_demand_kw || 0, state.pmGeral.demand_kw);
state.pmGeral.thd_v_pct = noise(2.5, 0.1);
state.pmGeral.thd_i_pct = noise(8.0 + ccmTotalPower * 0.02, 0.1);

// ═══ TRANSFORMADOR (TR01) ═══
state.transformer.power_kw = totalPower;
state.transformer.power_kvar = totalReactivePower;
state.transformer.power_kva = totalApparentPower;
state.transformer.load_pct = (totalApparentPower / state.transformer.nominal_kva) * 100;
state.transformer.oil_temp_c = firstOrderLag(state.transformer.oil_temp_c, 45 + state.transformer.load_pct * 0.25, 600, dt);
state.transformer.winding_temp_c = state.transformer.oil_temp_c + state.transformer.load_pct * 0.15;
state.transformer.cooling_fans_on = state.transformer.oil_temp_c > 65;

// ═══ BANCO DE CAPACITORES (BC01) ═══
if (state.capacitorBank.auto_mode) {
    const currentPF = state.pmGeral.power_factor;
    if (currentPF < state.capacitorBank.target_pf - 0.02 && state.capacitorBank.active_stages < state.capacitorBank.stages) {
        state.capacitorBank.active_stages++;
    } else if (currentPF > state.capacitorBank.target_pf + 0.03 && state.capacitorBank.active_stages > 0) {
        state.capacitorBank.active_stages--;
    }
}
state.capacitorBank.active_kvar = state.capacitorBank.active_stages * 25;
state.capacitorBank.current_pf = state.pmGeral.power_factor;
state.capacitorBank.voltage_v = noise(440, 0.005);
state.capacitorBank.current_a = state.capacitorBank.active_kvar * 1000 / (440 * 1.732);
state.capacitorBank.temperature_c = firstOrderLag(state.capacitorBank.temperature_c, 35 + state.capacitorBank.active_stages * 2, 300, dt);

// ═══ RELÉ DE PROTEÇÃO (REL_GERAL) ═══
state.mainRelay.f49_thermal_pct = (state.transformer.load_pct / 100) * 80;
state.mainRelay.f49_alarm = state.mainRelay.f49_thermal_pct > state.mainRelay.f49_alarm_pct;
state.mainRelay.f27_alarm = state.pmGeral.voltage_l1_v < state.mainRelay.f27_pickup_v * 1.02;
state.mainRelay.f59_alarm = state.pmGeral.voltage_l1_v > state.mainRelay.f59_pickup_v * 0.98;
state.mainRelay.any_alarm = state.mainRelay.f49_alarm || state.mainRelay.f27_alarm || state.mainRelay.f59_alarm;
state.mainRelay.any_trip = state.mainRelay.f50_51_trip || state.mainRelay.f49_trip || state.mainRelay.f27_trip || state.mainRelay.f59_trip;

// ═══ TOTALIZADORES ELÉTRICOS ═══
state.electricTotals.energy_kwh_today += (totalPower / 3600) * dt;
state.electricTotals.energy_kvarh_today += (Math.abs(totalReactivePower) / 3600) * dt;
state.electricTotals.runtime_h += dt / 3600;
if (totalPower > state.electricTotals.peak_demand_kw) {
    state.electricTotals.peak_demand_kw = totalPower;
    state.electricTotals.peak_demand_time = new Date().toISOString();
}
state.electricTotals.power_factor_avg = firstOrderLag(state.electricTotals.power_factor_avg, state.pmGeral.power_factor, 60, dt);

// Alarmes elétricos
checkAlarm(state.transformer.oil_temp_c > 75, 'TR01_OIL_HIGH_TEMP', `Trafo óleo temp alta: ${state.transformer.oil_temp_c.toFixed(1)}°C`, 'HIGH');
checkAlarm(state.transformer.load_pct > 90, 'TR01_OVERLOAD', `Trafo sobrecarga: ${state.transformer.load_pct.toFixed(0)}%`, 'HIGH');
checkAlarm(state.pmGeral.power_factor < 0.85, 'PM_LOW_PF', `Fator de potência baixo: ${state.pmGeral.power_factor.toFixed(2)}`, 'MEDIUM');
checkAlarm(state.capacitorBank.temperature_c > 55, 'BC01_HIGH_TEMP', `Banco capacitores temp alta: ${state.capacitorBank.temperature_c.toFixed(1)}°C`, 'MEDIUM');
checkAlarm(state.mainRelay.any_alarm, 'REL_ALARM', 'Relé de proteção em alarme', 'HIGH');

state.totals.energy_kwh += (totalPower / 3600) * dt;

// ═══════════════════════════════════════════════════════════════
// SALVAR ESTADO E GERAR TAGS
// ═══════════════════════════════════════════════════════════════

context.set('state', state);

const data = [];

// ═══ TAGS DO SISTEMA ═══
data.push({ tag_name: 'SYS_RUNNING_PV', value: state.running ? 1 : 0, unit: '', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_MODE_PV', value: state.operation_mode === 'LOADING' ? 1 : 0, unit: '', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_RUNTIME_H_PV', value: state.totals.runtime_h, unit: 'h', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_TOTAL_POWER_KW_PV', value: totalPower, unit: 'kW', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_TOTAL_ENERGY_KWH_PV', value: state.totals.energy_kwh, unit: 'kWh', protocol: 'INTERNAL' });
data.push({ tag_name: 'SYS_ACTIVE_ALARMS_PV', value: state.alarms.length, unit: '', protocol: 'INTERNAL' });

// ═══ TAGS DOS VAZADORES (4 unidades - OPC-UA) ═══
state.gates.forEach((gate) => {
    const num = String(gate.id).padStart(2, '0');
    data.push({ tag_name: `ARZ_GATE${num}_OPENING_PV`, value: gate.opening, unit: '%', protocol: 'OPC-UA' });
    data.push({ tag_name: `ARZ_GATE${num}_SETPOINT_PV`, value: gate.setpoint, unit: '%', protocol: 'OPC-UA' });
    data.push({ tag_name: `ARZ_GATE${num}_FLOW_TPH_PV`, value: gate.flow, unit: 't/h', protocol: 'OPC-UA' });
    data.push({ tag_name: `ARZ_GATE${num}_FAULT_PV`, value: gate.fault ? 1 : 0, unit: '', protocol: 'OPC-UA' });
});

// ═══ TAGS DAS CORREIAS (MODBUS) ═══
Object.entries(state.belts).forEach(([name, belt]) => {
    data.push({ tag_name: `${name}_RUNNING_PV`, value: belt.running ? 1 : 0, unit: '', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_SPEED_MPS_PV`, value: belt.speed_mps, unit: 'm/s', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_FLOW_TPH_PV`, value: belt.flow_tph, unit: 't/h', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_LOAD_PCT_PV`, value: belt.load_pct, unit: '%', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_POWER_KW_PV`, value: belt.power_kw, unit: 'kW', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_CURRENT_A_PV`, value: belt.current_a, unit: 'A', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_MOTOR_TEMP_C_PV`, value: belt.motor_temp_c, unit: '°C', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_BEARING_TEMP_C_PV`, value: belt.bearing_temp_c, unit: '°C', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_VIBRATION_MMS_PV`, value: belt.vibration_mms, unit: 'mm/s', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_BELT_SLIP_PV`, value: belt.belt_slip ? 1 : 0, unit: '', protocol: 'MODBUS' });
    data.push({ tag_name: `${name}_PULLCORD_PV`, value: belt.pull_cord ? 1 : 0, unit: '', protocol: 'MODBUS' });
});

// ═══ TAGS DO ELEVADOR (PROFINET) ═══
data.push({ tag_name: 'ELV01_RUNNING_PV', value: state.elevator.running ? 1 : 0, unit: '', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_SPEED_MPS_PV', value: state.elevator.speed_mps, unit: 'm/s', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_FLOW_TPH_PV', value: state.elevator.flow_tph, unit: 't/h', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_POWER_KW_PV', value: state.elevator.power_kw, unit: 'kW', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_CURRENT_A_PV', value: state.elevator.current_a, unit: 'A', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_MOTOR_TEMP_C_PV', value: state.elevator.motor_temp_c, unit: '°C', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_BEARING_TEMP_C_PV', value: state.elevator.bearing_temp_c, unit: '°C', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_VIBRATION_MMS_PV', value: state.elevator.vibration_mms, unit: 'mm/s', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_BUCKET_COUNT_PV', value: state.elevator.bucket_count, unit: '', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_BOOT_LEVEL_PV', value: state.elevator.boot_level_pct, unit: '%', protocol: 'PROFINET' });
data.push({ tag_name: 'ELV01_HEAD_PRESS_PV', value: state.elevator.head_pressure, unit: '%', protocol: 'PROFINET' });

// ═══ TAGS DA BALANÇA DE FLUXO (PROFINET) - CRÍTICO! ═══
data.push({ tag_name: 'BLC01_FLOW_TPH_PV', value: state.scale.flow_tph, unit: 't/h', protocol: 'PROFINET' });
data.push({ tag_name: 'BLC01_FLOW_SP_PV', value: state.scale.flow_sp, unit: 't/h', protocol: 'PROFINET' });
data.push({ tag_name: 'BLC01_TOTAL_T_PV', value: state.scale.total_t, unit: 't', protocol: 'PROFINET' });
data.push({ tag_name: 'BLC01_DAILY_TOTAL_T_PV', value: state.scale.daily_total_t, unit: 't', protocol: 'PROFINET' });
data.push({ tag_name: 'BLC01_SPEED_MPS_PV', value: state.scale.speed_mps, unit: 'm/s', protocol: 'PROFINET' });
data.push({ tag_name: 'BLC01_BELT_LOAD_KGM_PV', value: state.scale.belt_load_kg_m, unit: 'kg/m', protocol: 'PROFINET' });
data.push({ tag_name: 'BLC01_CAL_OK_PV', value: state.scale.calibration_ok ? 1 : 0, unit: '', protocol: 'PROFINET' });
data.push({ tag_name: 'BLC01_ZERO_OK_PV', value: state.scale.zero_ok ? 1 : 0, unit: '', protocol: 'PROFINET' });

// ═══ TAGS DO TRIPPER (ETHERNET/IP) ═══
data.push({ tag_name: 'TRP01_POSITION_M_PV', value: state.tripper.position_m, unit: 'm', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'TRP01_SPEED_MPM_PV', value: state.tripper.speed_mpm, unit: 'm/min', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'TRP01_TARGET_M_PV', value: state.tripper.target_position, unit: 'm', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'TRP01_BAY_SEL_PV', value: state.tripper.bay_selected, unit: '', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'TRP01_LIMIT_LEFT_PV', value: state.tripper.limit_left ? 1 : 0, unit: '', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'TRP01_LIMIT_RIGHT_PV', value: state.tripper.limit_right ? 1 : 0, unit: '', protocol: 'ETHERNET/IP' });

// ═══ TAGS DO SHIPLOADER (ETHERNET/IP) ═══
data.push({ tag_name: 'SLD01_FLOW_TPH_PV', value: state.shiploader.flow_tph, unit: 't/h', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_FLOW_SP_PV', value: state.shiploader.flow_sp, unit: 't/h', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_POWER_KW_PV', value: state.shiploader.power_kw, unit: 'kW', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_CURRENT_A_PV', value: state.shiploader.current_a, unit: 'A', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_BOOM_ANGLE_PV', value: state.shiploader.boom_angle_deg, unit: '°', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_SLEWING_PV', value: state.shiploader.slewing_deg, unit: '°', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_SHUTTLE_POS_PV', value: state.shiploader.shuttle_pos_m, unit: 'm', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_LOADED_T_PV', value: state.shiploader.loaded_t, unit: 't', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_TARGET_T_PV', value: state.shiploader.target_t, unit: 't', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_PROGRESS_PCT_PV', value: (state.shiploader.loaded_t / state.shiploader.target_t) * 100, unit: '%', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_TRIMMING_PV', value: state.shiploader.trimming_on ? 1 : 0, unit: '', protocol: 'ETHERNET/IP' });
data.push({ tag_name: 'SLD01_DUST_SUPP_PV', value: state.shiploader.dust_supp_on ? 1 : 0, unit: '', protocol: 'ETHERNET/IP' });

// ═══ TAGS DO ARMAZÉM ═══
data.push({ tag_name: 'WH_STOCK_T_PV', value: state.warehouse.stock_t, unit: 't', protocol: 'INTERNAL' });
data.push({ tag_name: 'WH_CAPACITY_T_PV', value: state.warehouse.capacity_t, unit: 't', protocol: 'INTERNAL' });
data.push({ tag_name: 'WH_LEVEL_PCT_PV', value: (state.warehouse.stock_t / state.warehouse.capacity_t) * 100, unit: '%', protocol: 'INTERNAL' });
data.push({ tag_name: 'WH_MOISTURE_PCT_PV', value: state.warehouse.moisture_pct, unit: '%', protocol: 'INTERNAL' });
data.push({ tag_name: 'WH_TEMP_C_PV', value: state.warehouse.temperature_c, unit: '°C', protocol: 'INTERNAL' });

// ═══════════════════════════════════════════════════════════════
// TAGS DO ELETROCENTRO
// ═══════════════════════════════════════════════════════════════

// ═══ TRANSFORMADOR (TR01) ═══
