}
node.status({fill:'red', shape:'dot', text:`Error: ${msg.statusCode}`});
return msg;

// ═══════════════════════════════════════════════════════════════
// COMMAND PROCESSOR - Control Equipment
// ═══════════════════════════════════════════════════════════════
// Commands:
//   equipment/start   - Liga equipamento
//   equipment/stop    - Desliga equipamento
//   equipment/fault   - Simula falha
//   equipment/clear   - Limpa falha
//   gate/setpoint     - Define abertura vazador
//   system/start      - Liga todo o sistema
//   system/stop       - Para todo o sistema
//   alarm/trigger     - Dispara alarme específico
//   alarm/clear       - Limpa alarme
// ═══════════════════════════════════════════════════════════════

let state = context.get('state') || global.get('grain_terminal_state');

if (!state) {
    msg.payload = { success: false, error: 'Simulator not initialized' };
    msg.statusCode = 500;
    return msg;
}

const cmd = msg.payload;
const command = cmd.command || '';
const target = cmd.target || '';
const value = cmd.value;

let result = { success: true, command, target };

try {
    switch (command) {
        // ═══ COMANDOS DE EQUIPAMENTO ═══
        case 'equipment/start':
            if (target === 'CORR01') {
                state.belts.CORR01.running = true;
                state.ccm.drawer1.breaker_on = true;
            } else if (target === 'CORR02') {
                state.belts.CORR02.running = true;
                state.ccm.drawer2.breaker_on = true;
            } else if (target === 'CORR03') {
                state.belts.CORR03.running = true;
                state.ccm.drawer3.breaker_on = true;
            } else if (target === 'ELV01') {
                state.elevator.running = true;
                state.ccm.drawer4.breaker_on = true;
            } else if (target === 'SLD01') {
                state.shiploader.flow_sp = 1800;
                state.ccm.drawer5.breaker_on = true;
                state.ccm.drawer6.breaker_on = true;
                state.ccm.drawer7.breaker_on = true;
            } else if (target === 'TRP01') {
                state.ccm.drawer8.breaker_on = true;
            } else {
                result.success = false;
                result.error = `Unknown equipment: ${target}`;
            }
            result.message = `${target} started`;
            break;

        case 'equipment/stop':
            if (target === 'CORR01') {
                state.belts.CORR01.running = false;
                state.ccm.drawer1.breaker_on = false;
            } else if (target === 'CORR02') {
                state.belts.CORR02.running = false;
                state.ccm.drawer2.breaker_on = false;
            } else if (target === 'CORR03') {
                state.belts.CORR03.running = false;
                state.ccm.drawer3.breaker_on = false;
            } else if (target === 'ELV01') {
                state.elevator.running = false;
                state.ccm.drawer4.breaker_on = false;
            } else if (target === 'SLD01') {
                state.shiploader.flow_sp = 0;
                state.ccm.drawer5.breaker_on = false;
                state.ccm.drawer6.breaker_on = false;
                state.ccm.drawer7.breaker_on = false;
            } else if (target === 'TRP01') {
                state.ccm.drawer8.breaker_on = false;
            } else {
                result.success = false;
                result.error = `Unknown equipment: ${target}`;
            }
            result.message = `${target} stopped`;
            break;

        case 'equipment/fault':
            if (target === 'CORR01') {
                state.belts.CORR01.running = false;
                state.ccm.drawer1.fault = true;
                state.ccm.drawer1.overload_trip = true;
            } else if (target === 'CORR02') {
                state.belts.CORR02.running = false;
                state.ccm.drawer2.fault = true;
                state.ccm.drawer2.overload_trip = true;
            } else if (target === 'CORR03') {
                state.belts.CORR03.running = false;
                state.ccm.drawer3.fault = true;
                state.ccm.drawer3.overload_trip = true;
            } else if (target === 'ELV01') {
                state.elevator.running = false;
                state.ccm.drawer4.fault = true;
                state.ccm.drawer4.overload_trip = true;
            } else if (target.startsWith('ARZ_GATE')) {
                const gateNum = parseInt(target.replace('ARZ_GATE', '')) - 1;
                if (gateNum >= 0 && gateNum < state.gates.length) {
                    state.gates[gateNum].fault = true;
                }
            } else {
                result.success = false;
                result.error = `Unknown equipment: ${target}`;
            }
            result.message = `${target} fault triggered`;
            break;

        case 'equipment/clear':
            if (target === 'CORR01') {
                state.ccm.drawer1.fault = false;
                state.ccm.drawer1.overload_trip = false;
            } else if (target === 'CORR02') {
                state.ccm.drawer2.fault = false;
                state.ccm.drawer2.overload_trip = false;
            } else if (target === 'CORR03') {
                state.ccm.drawer3.fault = false;
                state.ccm.drawer3.overload_trip = false;
            } else if (target === 'ELV01') {
                state.ccm.drawer4.fault = false;
                state.ccm.drawer4.overload_trip = false;
            } else if (target.startsWith('ARZ_GATE')) {
                const gateNum = parseInt(target.replace('ARZ_GATE', '')) - 1;
                if (gateNum >= 0 && gateNum < state.gates.length) {
                    state.gates[gateNum].fault = false;
                }
            } else if (target === 'ALL') {
                Object.values(state.ccm).forEach(d => {
                    d.fault = false;
                    d.overload_trip = false;
                });
                state.gates.forEach(g => g.fault = false);
            }
            result.message = `${target} fault cleared`;
            break;

        // ═══ COMANDOS DE VAZADOR ═══
        case 'gate/setpoint':
            const gateIdx = parseInt(target.replace('ARZ_GATE', '')) - 1;
            if (gateIdx >= 0 && gateIdx < state.gates.length) {
                state.gates[gateIdx].setpoint = Math.max(0, Math.min(100, value || 0));
                result.message = `Gate ${gateIdx + 1} setpoint: ${state.gates[gateIdx].setpoint}%`;
            } else {
                result.success = false;
                result.error = `Invalid gate: ${target}`;
            }
            break;

        // ═══ COMANDOS DE SISTEMA ═══
        case 'system/start':
            state.running = true;
            state.operation_mode = 'LOADING';
            state.belts.CORR01.running = true;
            state.belts.CORR02.running = true;
            state.belts.CORR03.running = true;
            state.elevator.running = true;
            state.shiploader.flow_sp = 1800;
            state.gates.forEach(g => g.setpoint = 75);
            Object.values(state.ccm).forEach(d => d.breaker_on = true);
            state.transformer.energized = true;
            result.message = 'System started - All equipment running';
            break;

        case 'system/stop':
            state.running = false;
            state.operation_mode = 'IDLE';
            state.belts.CORR01.running = false;
            state.belts.CORR02.running = false;
            state.belts.CORR03.running = false;
            state.elevator.running = false;
            state.shiploader.flow_sp = 0;
            state.gates.forEach(g => g.setpoint = 0);
            result.message = 'System stopped - All equipment idle';
            break;

        case 'system/emergency':
            state.running = false;
            state.operation_mode = 'EMERGENCY';
            state.belts.CORR01.running = false;
            state.belts.CORR01.pull_cord = true;
            state.belts.CORR02.running = false;
            state.belts.CORR02.pull_cord = true;
            state.belts.CORR03.running = false;
            state.belts.CORR03.pull_cord = true;
            state.elevator.running = false;
            state.shiploader.flow_sp = 0;
            state.gates.forEach(g => g.setpoint = 0);
            Object.values(state.ccm).forEach(d => d.breaker_on = false);
            result.message = 'EMERGENCY STOP - All equipment tripped';
            break;

        // ═══ COMANDOS DE ALARME ═══
        case 'alarm/trigger':
            if (target === 'TR01_OVERTEMP') {
                state.transformer.oil_temp_c = 85;
            } else if (target === 'TR01_OVERLOAD') {
                state.transformer.load_pct = 110;
            } else if (target === 'LOW_PF') {
                state.capacitorBank.active_stages = 0;
            } else if (target === 'UNDERVOLTAGE') {
                state.pmGeral.voltage_l1_v = 380;
                state.pmGeral.voltage_l2_v = 382;
                state.pmGeral.voltage_l3_v = 378;
            } else if (target === 'OVERVOLTAGE') {
                state.pmGeral.voltage_l1_v = 490;
                state.pmGeral.voltage_l2_v = 488;
                state.pmGeral.voltage_l3_v = 492;
            } else if (target === 'RELAY_TRIP') {
                state.mainRelay.f50_51_trip = true;
                state.mainRelay.any_trip = true;
            }
            result.message = `Alarm ${target} triggered`;
            break;

        case 'alarm/clear':
            if (target === 'ALL') {
                state.alarms = [];
                state.mainRelay.f50_51_trip = false;
                state.mainRelay.f49_trip = false;
                state.mainRelay.f27_trip = false;
                state.mainRelay.f59_trip = false;
                state.mainRelay.f81_trip = false;
                state.mainRelay.any_trip = false;
                state.mainRelay.any_alarm = false;
                state.belts.CORR01.pull_cord = false;
                state.belts.CORR02.pull_cord = false;
                state.belts.CORR03.pull_cord = false;
            }
            result.message = 'Alarms cleared';
            break;

        // ═══ COMANDOS DE ENERGIA ═══
        case 'capacitor/auto':
            state.capacitorBank.auto_mode = value !== false;
            result.message = `Capacitor bank auto mode: ${state.capacitorBank.auto_mode}`;
            break;

        case 'capacitor/stages':
            state.capacitorBank.active_stages = Math.max(0, Math.min(8, value || 0));
            result.message = `Capacitor bank stages: ${state.capacitorBank.active_stages}`;
            break;

        case 'transformer/tap':
            state.transformer.tap_position = Math.max(1, Math.min(5, value || 3));
            result.message = `Transformer tap: ${state.transformer.tap_position}`;
            break;

        // ═══ STATUS ═══
        case 'status/get':
            result.status = {
                running: state.running,
                mode: state.operation_mode,
                equipment: {
                    CORR01: { running: state.belts.CORR01.running, fault: state.ccm.drawer1.fault, power_kw: state.belts.CORR01.power_kw },
                    CORR02: { running: state.belts.CORR02.running, fault: state.ccm.drawer2.fault, power_kw: state.belts.CORR02.power_kw },
                    CORR03: { running: state.belts.CORR03.running, fault: state.ccm.drawer3.fault, power_kw: state.belts.CORR03.power_kw },
                    ELV01: { running: state.elevator.running, fault: state.ccm.drawer4.fault, power_kw: state.elevator.power_kw },
                    SLD01: { running: state.shiploader.flow_tph > 0, power_kw: state.shiploader.power_kw }
                },
                electrical: {
                    total_power_kw: state.pmGeral.power_kw,
                    power_factor: state.pmGeral.power_factor,
                    transformer_load_pct: state.transformer.load_pct,
                    capacitor_stages: state.capacitorBank.active_stages
                },
                alarms: state.alarms.length,
                flow_tph: state.scale.flow_tph
            };
            break;

        default:
            result.success = false;
            result.error = `Unknown command: ${command}`;
    }
} catch (err) {
    result.success = false;
    result.error = err.message;
}

// Salva estado atualizado
context.set('state', state);
global.set('grain_terminal_state', state);

msg.payload = result;
msg.statusCode = result.success ? 200 : 400;

node.status({
    fill: result.success ? 'green' : 'red',
    shape: 'dot',
    text: `${command} ${target}`
});

return msg;

const state = global.get('grain_terminal_state');

if (!state) {
    msg.payload = { success: false, error: 'Simulator not running' };
    msg.statusCode = 500;
    return msg;
}

msg.payload = {
    success: true,
    timestamp: new Date().toISOString(),
    system: {
        running: state.running,
        mode: state.operation_mode,
        runtime_h: state.totals.runtime_h,
        time_s: state.time_s
    },
    process: {
        gates: state.gates.map(g => ({
            id: g.id,
            setpoint: g.setpoint,
            opening: g.opening,
            flow_tph: g.flow,
            fault: g.fault
        })),
        belts: Object.entries(state.belts).map(([name, b]) => ({
            name,
            running: b.running,
            speed_mps: b.speed_mps,
            flow_tph: b.flow_tph,
            load_pct: b.load_pct,
            power_kw: b.power_kw,
            motor_temp_c: b.motor_temp_c,
            pull_cord: b.pull_cord
        })),
        elevator: {
            running: state.elevator.running,
            speed_mps: state.elevator.speed_mps,
            flow_tph: state.elevator.flow_tph,
            power_kw: state.elevator.power_kw
        },
        scale: {
            flow_tph: state.scale.flow_tph,
            total_t: state.scale.total_t,
            daily_total_t: state.scale.daily_total_t
        },
        shiploader: {
            flow_tph: state.shiploader.flow_tph,
            loaded_t: state.shiploader.loaded_t,
            target_t: state.shiploader.target_t,
            progress_pct: (state.shiploader.loaded_t / state.shiploader.target_t) * 100
        }
    },
    electrical: {
        transformer: {
            energized: state.transformer.energized,
            power_kw: state.transformer.power_kw,
            power_kva: state.transformer.power_kva,
            load_pct: state.transformer.load_pct,
            oil_temp_c: state.transformer.oil_temp_c,
            cooling_fans_on: state.transformer.cooling_fans_on
        },
        power_meter: {
            voltage_v: state.pmGeral.voltage_l1_v,
            current_a: state.pmGeral.current_l1_a,
            power_kw: state.pmGeral.power_kw,
            power_kvar: state.pmGeral.power_kvar,
            power_factor: state.pmGeral.power_factor,
            frequency_hz: state.pmGeral.frequency_hz,
            thd_v_pct: state.pmGeral.thd_v_pct,
            thd_i_pct: state.pmGeral.thd_i_pct,
            energy_kwh: state.pmGeral.energy_kwh,
            demand_kw: state.pmGeral.demand_kw,
            max_demand_kw: state.pmGeral.max_demand_kw
        },
        capacitor_bank: {
            auto_mode: state.capacitorBank.auto_mode,
            active_stages: state.capacitorBank.active_stages,
            active_kvar: state.capacitorBank.active_kvar,
            temperature_c: state.capacitorBank.temperature_c
        },
        ccm: Object.entries(state.ccm).map(([id, d]) => ({
            id,
            name: d.name,
            running: d.running,
            breaker_on: d.breaker_on,
            fault: d.fault,
            overload_trip: d.overload_trip,
            power_kw: d.power_kw,
            current_a: d.current_a,
            thermal_pct: d.thermal_pct
        })),
        relay: {
            any_alarm: state.mainRelay.any_alarm,
            any_trip: state.mainRelay.any_trip,
            thermal_pct: state.mainRelay.f49_thermal_pct
        }
    },
    alarms: state.alarms,
    totals: {
        loaded_t: state.totals.loaded_t,
        energy_kwh: state.totals.energy_kwh,
        runtime_h: state.totals.runtime_h
    }
};

msg.statusCode = 200;
return msg;

// Obtém estado do simulador
const state = global.get('grain_terminal_state');

if (!state) {
    node.status({fill:'yellow', shape:'ring', text:'Waiting for simulator...'});
    return null;
}

// Prepara mensagens para atualizar valores no OPC-UA Server
const messages = [];

// ═══ VAZADORES (ARZ_GATES) ═══
state.gates.forEach((gate, i) => {
    const num = String(gate.id).padStart(2, '0');
    messages.push({
        topic: `ns=1;s=GrainTerminal.ARZ_GATE${num}.Opening`,
        payload: gate.opening
    });
    messages.push({
        topic: `ns=1;s=GrainTerminal.ARZ_GATE${num}.Setpoint`,
        payload: gate.setpoint
    });
    messages.push({
        topic: `ns=1;s=GrainTerminal.ARZ_GATE${num}.FlowTPH`,
        payload: gate.flow
    });
    messages.push({
        topic: `ns=1;s=GrainTerminal.ARZ_GATE${num}.Fault`,
        payload: gate.fault
    });
});

// ═══ TRANSFORMADOR (TR01) ═══
const tr = state.transformer;
messages.push({ topic: 'ns=1;s=GrainTerminal.TR01.PowerKW', payload: tr.power_kw });
messages.push({ topic: 'ns=1;s=GrainTerminal.TR01.PowerKVAR', payload: tr.power_kvar });
messages.push({ topic: 'ns=1;s=GrainTerminal.TR01.PowerKVA', payload: tr.power_kva });
messages.push({ topic: 'ns=1;s=GrainTerminal.TR01.LoadPct', payload: tr.load_pct });
messages.push({ topic: 'ns=1;s=GrainTerminal.TR01.OilTempC', payload: tr.oil_temp_c });
messages.push({ topic: 'ns=1;s=GrainTerminal.TR01.WindingTempC', payload: tr.winding_temp_c });
messages.push({ topic: 'ns=1;s=GrainTerminal.TR01.CoolingFansOn', payload: tr.cooling_fans_on });
messages.push({ topic: 'ns=1;s=GrainTerminal.TR01.Energized', payload: tr.energized });

// ═══ MULTIMEDIDOR GERAL (PM_GERAL) ═══
const pm = state.pmGeral;
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.VoltageL1', payload: pm.voltage_l1_v });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.VoltageL2', payload: pm.voltage_l2_v });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.VoltageL3', payload: pm.voltage_l3_v });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.CurrentL1', payload: pm.current_l1_a });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.CurrentL2', payload: pm.current_l2_a });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.CurrentL3', payload: pm.current_l3_a });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.PowerKW', payload: pm.power_kw });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.PowerKVAR', payload: pm.power_kvar });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.PowerFactor', payload: pm.power_factor });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.FrequencyHz', payload: pm.frequency_hz });
messages.push({ topic: 'ns=1;s=GrainTerminal.PM_GERAL.EnergyKWH', payload: pm.energy_kwh });

node.status({
    fill: 'green',
    shape: 'dot',
    text: `${messages.length} OPC-UA values`
});

// Retorna todas as mensagens
return [messages];
